input.source:
one sig Counter { var n: one Int }
fact { Counter.n = 0 }
fact { always { Counter.n' = plus[Counter.n, 1] } }
Wraps: run { eventually { Counter.n = -1 } } for 3 but 3 Int, 8 steps
NoLasso: run {} for 3 but 3 Int, 7 steps
AfterOne: check { after { Counter.n = 1 } } for 3 but 3 Int, 8 steps
Settles: check { eventually { always { Counter.n = 0 } } } for 3 but 3 Int, 8 steps

sig Item {}
one sig Box { var items: set Item }
pred grow { some i: Item - Box.items | Box.items' = Box.items + i }
pred stay { Box.items' = Box.items }
Grow: run { no Box.items and always { grow } } for 3 but 5 steps
GrowOrStay: run { no Box.items and always { grow or stay } and eventually { #Box.items = 3 } } for 3 but 5 steps
TooFew: run { no Box.items and always { grow or stay } and eventually { #Box.items = 3 } } for 3 but exactly 2 Item, 5 steps
ShortTrace: run { no Box.items and always { grow or stay } and eventually { #Box.items = 3 } } for 3 but 2 steps
Monotone: check { (no Box.items and always { grow or stay }) implies always { Box.items in Box.items' } } for 3 but 5 steps

abstract sig Color {}
one sig Red, Green extends Color {}
one sig Light { var color: one Color }
fact { Light.color = Red }
fact { always { Light.color' != Light.color } }
Alternates: check { always { Light.color = Red implies after { Light.color = Green } } } for 3 but 4 steps
StaysRed: check { always { Light.color = Red } } for 3 but 4 steps
GreenEventually: check { eventually { Light.color = Green } } for 3 but 4 steps
SomeTrace: run {} for 3 but 4 steps
InitialOnly: run { Light.color = Green } for 3 but 4 steps

sig Proc {}
one sig Lock { var holder: lone Proc }
pred acquire[p: Proc] { no Lock.holder and Lock.holder' = p }
pred release[p: Proc] { Lock.holder = p and no Lock.holder' }
pred skip { Lock.holder' = Lock.holder }
fact { no Lock.holder }
fact { always { skip or (some p: Proc | acquire[p] or release[p]) } }
Safe: check { always { lone Lock.holder } } for 3 but 6 steps
Handover: run { some p, q: Proc | p != q and eventually { Lock.holder = p and eventually { Lock.holder = q } } } for 3 but 6 steps
NoHandoverWithOne: run { some p, q: Proc | p != q and eventually { Lock.holder = p and eventually { Lock.holder = q } } } for 3 but exactly 1 Proc, 6 steps
Released: check { all p: Proc | always { Lock.holder = p implies eventually { no Lock.holder } } } for 3 but 4 steps
OnlyFromFree: check { always { (some Lock.holder' and Lock.holder' != Lock.holder) implies no Lock.holder } } for 3 but 6 steps

sig Node { edges: set Node }
one sig Token { var at: one Node }
fact { always { Token.at' in Token.at.edges } }
Cycle: run { some n: Node | always { eventually { Token.at = n } } } for 3 but 4 steps
VisitAll: run { #Node = 3 and (all n: Node | eventually { Token.at = n }) } for 3 but 3 steps
VisitAllShort: run { #Node = 3 and (all n: Node | eventually { Token.at = n }) } for 3 but 2 steps
Stuck: run { no edges } for 3 but 4 steps
Reachable: check { all n: Node | Token.at = n implies always { Token.at in n.*edges } } for 3 but 4 steps
Unreachable: check { all n: Node | Token.at = n implies always { Token.at in n.^edges } } for 3 but 4 steps
